-- BEGIN CANONICAL MIGRATION 0034 20260823135800 kam_phase2_generate_missions_l3_l5
with targets as (
  select * from (values
    ('L3','How ',' Works','How does this work in aviation?','Explain the basic process behind: '),
    ('L4','Professional Decision: ','','What decision would an aviation professional make?','Apply safety and operational thinking to: '),
    ('L5','Career Path: ','','Which aviation career uses this knowledge?','')
  ) as t(level_code,title_prefix,title_suffix,big_question,goal_prefix)
), base as (
  select m.*, split_part(m.code,'-',2) season_no, split_part(m.code,'-',3) mission_no_code
  from public.kids_missions m
  where m.code like 'L1-S%-M%'
), generated as (
  select
    t.level_code,
    t.level_code || '-' || b.season_no || '-' || b.mission_no_code as code,
    t.level_code || '-' || b.season_no as season_code,
    b.mission_no,
    case when t.level_code='L3' then t.title_prefix || b.title || t.title_suffix
         else t.title_prefix || b.title end as title,
    t.big_question as big_question,
    case when t.level_code='L5' then 'Connect this topic to career skills and aviation pathways.'
         else t.goal_prefix || lower(left(b.learning_goal,1)) || substr(b.learning_goal,2) end as learning_goal,
    b.stamp_name,
    case
      when b.code='L1-S10-M12' and t.level_code='L3' then 'L4-S1-M1'
      when b.code='L1-S10-M12' and t.level_code='L4' then 'L5-S1-M1'
      when b.code='L1-S10-M12' and t.level_code='L5' then 'PROGRAM-COMPLETE'
      else regexp_replace(b.next_mission_code,'^L1-',t.level_code || '-')
    end as next_mission_code,
    b.production_status,
    b.sort_order
  from base b cross join targets t
)
insert into public.kids_missions(season_id,code,mission_no,name,title,description,big_question,learning_goal,learning_objectives,stamp_name,next_mission_code,production_status,sort_order,is_active)
select s.id,g.code,g.mission_no,g.title,g.title,g.learning_goal,g.big_question,g.learning_goal,ARRAY[g.learning_goal]::text[],g.stamp_name,g.next_mission_code,g.production_status,g.sort_order,true
from generated g join public.kids_seasons s on s.code=g.season_code
on conflict (code) do update set
 season_id=excluded.season_id, mission_no=excluded.mission_no, name=excluded.name, title=excluded.title,
 description=excluded.description,big_question=excluded.big_question,learning_goal=excluded.learning_goal,
 learning_objectives=excluded.learning_objectives,stamp_name=excluded.stamp_name,next_mission_code=excluded.next_mission_code,
 production_status=excluded.production_status,sort_order=excluded.sort_order,is_active=true,updated_at=now();
-- END CANONICAL MIGRATION 0034

-- BEGIN CANONICAL MIGRATION 0035 20260823135928 kam_phase2_generate_blueprints
with skill_values as (
  select ARRAY['Decision Making','Problem Solving','Map Reading','Safety Awareness','Sequencing','Comparison','Observation','Communication']::text[] skills,
         ARRAY['Respect','Teamwork','Safety','Confidence','Global Awareness','Patience','Curiosity','Responsibility']::text[] vals
), src as (
  select m.id as mission_id,m.code,m.stamp_name,m.next_mission_code,
         split_part(m.code,'-',1) level_code,
         substring(split_part(m.code,'-',2) from 2)::int season_no,
         substring(split_part(m.code,'-',3) from 2)::int mission_no,
         b.title as base_title
  from public.kids_missions m
  join public.kids_missions b on b.code=regexp_replace(m.code,'^L[1-5]-','L1-')
), prepared as (
  select s.*,
    regexp_split_to_array(
      trim(regexp_replace(regexp_replace(replace(s.base_title,'-',''),'[0-9]+','','g'),'[^A-Za-z]+',' ','g')),
      '\s+'
    )::text[] as concepts,
    ((s.season_no+s.mission_no-2)%8)+1 as skill_ix,
    (((substring(s.level_code from 2))::int+s.mission_no-2)%8)+1 as value_ix
  from src s
)
insert into public.kids_mission_blueprints(mission_id,key_concepts,vocabulary,primary_skill,primary_value,aviation_connection,stamp_name,next_mission_code,status)
select p.mission_id,p.concepts,p.concepts,sv.skills[p.skill_ix],sv.vals[p.value_ix],
       'Airport / Aircraft / Flight / People / Travel',p.stamp_name,p.next_mission_code,'Not Started'
from prepared p cross join skill_values sv
on conflict (mission_id) do update set
 key_concepts=excluded.key_concepts,vocabulary=excluded.vocabulary,primary_skill=excluded.primary_skill,
 primary_value=excluded.primary_value,aviation_connection=excluded.aviation_connection,stamp_name=excluded.stamp_name,
 next_mission_code=excluded.next_mission_code,status=excluded.status,updated_at=now();
-- END CANONICAL MIGRATION 0035

-- BEGIN CANONICAL MIGRATION 0036 20260823135955 kam_phase2_generate_learning_matrix
with constants as (
  select ARRAY['Observation','Communication','Problem Solving']::text[] skills,
         ARRAY['Curiosity','Responsibility','Teamwork','Safety']::text[] vals
), src as (
  select m.id as mission_id,
         substring(split_part(m.code,'-',2) from 2)::int season_no,
         substring(split_part(m.code,'-',3) from 2)::int mission_no
  from public.kids_missions m
), prepared as (
  select s.*,
    case s.season_no
      when 1 then 'preparing to travel'
      when 2 then 'welcome to the airport'
      when 3 then 'getting ready to fly'
      when 4 then 'meet the aviation team'
      when 5 then 'inside the aircraft'
      when 6 then 'my first flight'
      when 7 then 'around the world'
      when 8 then 'amazing places'
      when 9 then 'weather and travel'
      when 10 then 'aviation explorer graduation'
    end as theme
  from src s
)
insert into public.kids_learning_matrix(mission_id,knowledge_goal,primary_skill,primary_value,vocabulary_set,aviation_link,difficulty,status,review_notes)
select p.mission_id,
       'Understand ' || p.theme || ' concept ' || p.mission_no,
       c.skills[((p.mission_no-1)%3)+1],
       c.vals[((p.mission_no-1)%4)+1],
       '5 words max','Airport / Travel / Flight','Age Appropriate','Planned',''
from prepared p cross join constants c
on conflict (mission_id) do update set
 knowledge_goal=excluded.knowledge_goal,primary_skill=excluded.primary_skill,primary_value=excluded.primary_value,
 vocabulary_set=excluded.vocabulary_set,aviation_link=excluded.aviation_link,difficulty=excluded.difficulty,
 status=excluded.status,review_notes=excluded.review_notes,updated_at=now();
-- END CANONICAL MIGRATION 0036

